-- Questões originais: Fernandes e Abreu, Implantando a Governança de TI, 4ª edição, Brasport, 2014.
-- Contexto histórico da edição: COBIT 5, ITIL 2011 e versões de normas nela apresentadas.
-- Não são questões oficiais nem exercícios transcritos do livro.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas referem-se ao arquivo PDF fornecido, não à paginação impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 15: Governança de TI para Pequenas e Médias Empresas — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('bab78c12-6e35-50ac-86f1-55d105d50403', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Governança de TI', 'Fácil', 'Para pequenas e médias empresas, os autores propõem uma governança principalmente baseada em:', '["Estrutura idêntica à de uma multinacional.","Práticas gerenciais proporcionais à realidade da empresa.","Ausência de planejamento.","Certificação prévia obrigatória de todos.","Aquisição de todas as ferramentas do mercado."]'::jsonb, 1, 'A adaptação permite introduzir controles e gestão sem exigir estruturas desproporcionais.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('fa3e356b-433a-5666-ba2b-8f1bbbf153dc', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Governança de TI', 'Médio', 'Qual limitação é apontada como frequente na TI das pequenas empresas descritas?', '["Excesso universal de especialistas.","Capacidade técnica sempre ilimitada.","Obrigação de desenvolver todo software.","Ausência total de terceirização.","Restrição de habilidades internas."]'::jsonb, 4, 'O cenário discutido inclui limitações de conhecimento e recursos.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('ebf677aa-9123-51a7-ab4c-3e7c444960d0', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Governança de TI', 'Médio', 'Uma pequena empresa deve decidir sobre TI considerando principalmente:', '["Apenas a oferta mais recente.","Somente preferências técnicas.","Exclusivamente o número de computadores.","Somente a experiência de outra empresa.","Continuidade, crescimento, custos e riscos do negócio."]'::jsonb, 4, 'As práticas propostas ligam investimentos às necessidades empresariais.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1f4fd39a-f818-5bbd-88a8-990dacbc84d1', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Governança de TI', 'Fácil', 'Qual ação simples ajuda a planejar a TI de uma pequena empresa?', '["Suspender inventários.","Comprar capacidade sem avaliar demanda.","Copiar o orçamento de um fornecedor.","Conversar com a direção sobre planos de crescimento.","Esperar a infraestrutura falhar."]'::jsonb, 3, 'Entender os planos do negócio permite antecipar necessidades de sistemas e recursos.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7eed4c9e-3ce4-59d6-bdf0-b4487355a95c', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Governança de TI', 'Médio', 'Ao selecionar software, por que avaliar o custo total de propriedade?', '["Ele garante lucro imediato.","Ele considera apenas a licença inicial.","O preço de compra não abrange necessariamente todos os custos.","Ele elimina custos de manutenção.","Ele substitui requisitos funcionais."]'::jsonb, 2, 'Implantação, treinamento, suporte e evolução também podem gerar custos.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c1b3b67e-f672-508c-9d3c-f4a9006b0285', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Governança de TI', 'Médio', 'Consultar clientes atuais de um fornecedor ajuda a avaliar:', '["Somente o tamanho do logotipo.","Apenas a quantidade de anúncios.","Exclusivamente o valor patrimonial.","Qualidade e credibilidade da solução e do atendimento.","Somente a marca dos servidores."]'::jsonb, 3, 'A experiência de uso complementa a proposta comercial.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b18ac002-d363-5901-b870-f89349c2ec68', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Governança de TI', 'Médio', 'Na contratação de sistemas, por que envolver usuários na escolha?', '["Para transferir toda responsabilidade contratual.","Para dispensar análise técnica.","Eles ajudam a avaliar necessidades e adequação ao uso.","Para eliminar os testes.","Para impedir mudanças futuras."]'::jsonb, 2, 'A participação contribui para uma escolha coerente com o trabalho real.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2beb771f-151e-5d0c-b3b6-b48a9148ced6', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Governança de TI', 'Médio', 'Uma nova aplicação será integrada ao legado. Qual cuidado é recomendado?', '["Plano de integração, testes e contingência.","Excluir backups antigos antes do teste.","Somente instalar diretamente em produção.","Apenas trocar as senhas.","Dispensar participação do fornecedor."]'::jsonb, 0, 'A integração pode afetar continuidade e precisa ser planejada.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7f4a1ef1-cd31-578b-abef-5a5f24545256', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Governança de TI', 'Médio', 'Solicitar plano de testes e participação dos usuários na homologação reduz qual risco?', '["Exclusivamente atraso de faturamento do fornecedor.","Apenas variação cambial.","Somente custo contábil de depreciação.","Aceitar solução inadequada ao uso esperado.","Somente obsolescência física de cabos."]'::jsonb, 3, 'A homologação verifica se a solução atende às necessidades acordadas.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('663a2d11-ee03-55fb-a5e4-e9a7d81fa913', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Governança de TI', 'Médio', 'Por que avaliar capacidade antes de incorporar novas soluções?', '["A capacidade é irrelevante se houver contrato.","Toda aplicação nova reduz consumo.","Somente o número de usuários cadastrados importa.","A demanda adicional pode superar os recursos disponíveis.","Todo fornecedor garante capacidade ilimitada."]'::jsonb, 3, 'O planejamento deve considerar crescimento e requisitos dos novos sistemas.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('56fe488b-9b15-5fe7-8028-d0c394fa7c1e', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Governança de TI', 'Fácil', 'Qual prática ajuda a conhecer os recursos computacionais existentes?', '["Exclusivamente análise de vendas.","Somente divulgação de resultados.","Apenas controle de férias.","Somente avaliação de fornecedores.","Inventário periódico."]'::jsonb, 4, 'O inventário apoia configuração, manutenção e planejamento.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8edeb691-1781-5c89-b5db-29ea38d8bd88', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Governança de TI', 'Médio', 'Integrar informações do RH à gestão de acessos permite:', '["Eliminar qualquer registro de uso.","Criar acesso permanente para todos.","Ajustar privilégios quando pessoas entram ou saem.","Dispensar autorização de acesso.","Transferir a segurança ao funcionário."]'::jsonb, 2, 'O ciclo de vida de acessos deve acompanhar vínculos e funções.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('067dfbb3-f27f-5369-b727-2b38e60891d0', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Governança de TI', 'Fácil', 'Registrar chamados de usuários ajuda principalmente a:', '["Garantir ausência de incidentes.","Substituir a gestão do orçamento.","Dispensar responsáveis pelos serviços.","Eliminar a necessidade de suporte.","Acompanhar atendimento e analisar recorrências."]'::jsonb, 4, 'Os registros permitem identificar problemas frequentes e orientar melhorias.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('4d25ef25-9d31-50f0-a700-829ef95a26c8', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Governança de TI', 'Médio', 'Analisar causas dos incidentes mais frequentes deve resultar em:', '["Ações para reduzir sua ocorrência.","Exclusão dos registros sem avaliação.","Suspensão do canal de suporte.","Somente alteração da numeração dos chamados.","Aumento automático do prazo de atendimento."]'::jsonb, 0, 'O histórico deve alimentar correções, não apenas estatísticas.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('85459699-e747-5be5-82a3-e23261a58838', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Governança de TI', 'Médio', 'A gestão dos contratos terceirizados deve acompanhar principalmente:', '["Somente endereço do fornecedor.","Apenas data de assinatura.","Níveis de serviço e progresso das entregas.","Somente emissão das notas fiscais.","Exclusivamente número de propostas anteriores."]'::jsonb, 2, 'O acompanhamento verifica se o serviço contratado está sendo entregue.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c9761c36-47e0-5208-be7a-d926ba8c8077', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Governança de TI', 'Médio', 'Qual atitude é recomendada em relação ao orçamento de TI?', '["Planejar, controlar e explicar seus impactos ao negócio.","Elaborá-lo apenas após gastar.","Limitá-lo ao preço de equipamentos.","Considerá-lo independente dos serviços.","Omiti-lo da direção."]'::jsonb, 0, 'O orçamento sustenta o funcionamento e a evolução da empresa.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('66742b95-a4b3-575e-b502-d9b3de84d4fe', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Governança de TI', 'Médio', 'Apresentar apenas quantidade de chamados à direção pode ser insuficiente porque:', '["A direção só pode avaliar marcas de hardware.","É preciso demonstrar resultados e benefícios para a empresa.","Chamados nunca são úteis.","Indicadores operacionais são proibidos.","Todo benefício é igual ao custo."]'::jsonb, 1, 'A comunicação deve mostrar atendimento, disponibilidade, custos e ganhos relevantes.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('e628d3ea-4bdc-5d01-b362-7ee839f253c9', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Governança de TI', 'Difícil', 'O único responsável de TI passa todo o tempo em suporte e nunca planeja. Qual barreira do capítulo aparece?', '["Excesso de governança corporativa.","Acúmulo de funções operacionais e gerenciais.","Sobra de competências especializadas.","Independência excessiva da auditoria.","Abundância de recursos financeiros."]'::jsonb, 1, 'A sobrecarga reduz a interação com a direção e a gestão do futuro.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('539d973e-ad07-5192-8237-d94d178bad0d', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Governança de TI', 'Médio', 'Como enfrentar a alta tolerância da direção a riscos de TI?', '["Demonstrar impactos sobre continuidade e crescimento, preferencialmente quantificados.","Ocultar incidentes para evitar preocupação.","Eliminar a avaliação de riscos.","Comprar ferramentas sem autorização.","Apenas divulgar termos técnicos."]'::jsonb, 0, 'A comunicação deve traduzir exposição tecnológica em consequências empresariais.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('dcc590c1-71f0-5ef4-8109-e62d1a19a6cd', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Governança de TI', 'Médio', 'É necessário esperar um plano sofisticado para iniciar todas as práticas recomendadas às pequenas empresas?', '["Sim, e nada pode ser feito antes.","Não; elas podem ser adotadas gradualmente.","Não, porque planejamento nunca é útil.","Sim, apenas após criar um departamento independente.","Sim, com certificação obrigatória."]'::jsonb, 1, 'O livro propõe adoção passo a passo conforme as possibilidades.', 'FERNANDES, Aguinaldo Aragon; ABREU, Vladimir Ferraz de. Implantando a Governança de TI: da estratégia à gestão dos processos e serviços. 4ª edição. Brasport, 2014. Capítulo 15, páginas 592–599 do PDF fornecido. Contexto histórico da edição de 2014. Questão original de estudo; não é questão oficial do CP-T.', false, false)
ON CONFLICT (id) DO NOTHING;

COMMIT;
